// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address depositor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(depositor != address(0));
        amount = bound(amount, 0, 1 ether);
        uint256 before = c.depositsCount();
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);
        // General rule: a successful deposit raises the counter by exactly one.
        assertTrue(c.depositsCount() == before + 1);
    }
}
